/**
 * CM-EIP extension questions.
 *
 * Emitted by `scripts/append-questions.mjs` in the `### N. **[Type]** [REF] stem /
 * - a. … / <details>…` shape this bank uses. Every item carries a source tag so
 * `audit-coverage.mjs` can attribute it to a syllabus row; the tag is also what
 * `parseBank` reads the section number from.
 *
 * Shape: { c, t, s, q, o: [4], a, r }
 *   c = chapter key as the parser derives it: '1'..'12' or 'appendix-A'..'appendix-D'
 *   t = Single choice | Multiple response | Calculation | Scenario
 *   s = source tag, e.g. 'CM-EIP §4.2' or 'CM-EIP Appendix B'
 *   a = one letter, or several comma-separated for multiple response
 *
 * Every calculation is worked in the rationale and the correct value is present
 * in the option list.
 */

